import{_ as e,o as t,c as r,a2 as i}from"./chunks/framework.C0KMm31j.js";const h="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_16_actor_critic.png",l="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_16_critic_target.png",o="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_16_actor_gradient.png",n="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_16_exploration_modes.png",d="/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_16_driving_boundary.png",P=JSON.parse('{"title":"连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进","description":"DQN（深度 Q 网络）可以比较有限个动作的价值，却无法在方向盘角度、加速度或机械臂力矩这样的连续空间里逐项枚举。Deep Deterministic Policy Gradient（深度确定性策略梯度，DDPG）为连续控制搭建了一条直接路径：Actor（演员）网络把状态映射成确定性动作，Criti","frontmatter":{"title":"连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进","description":"DQN（深度 Q 网络）可以比较有限个动作的价值，却无法在方向盘角度、加速度或机械臂力矩这样的连续空间里逐项枚举。Deep Deterministic Policy Gradient（深度确定性策略梯度，DDPG）为连续控制搭建了一条直接路径：Actor（演员）网络把状态映射成确定性动作，Criti","date":"2026-08-13","topic":"强化学习","section":"强化学习分类系列","readingTime":13,"source":"2026-08-13/rl_series_16_ddpg.md","status":"published","cover":"/article-assets/2026-08-13/rl_series_16_actor_critic.png","head":[["link",{"rel":"canonical","href":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-16-ddpg"}],["meta",{"property":"og:type","content":"article"}],["meta",{"property":"og:title","content":"连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进"}],["meta",{"property":"og:description","content":"DQN（深度 Q 网络）可以比较有限个动作的价值，却无法在方向盘角度、加速度或机械臂力矩这样的连续空间里逐项枚举。Deep Deterministic Policy Gradient（深度确定性策略梯度，DDPG）为连续控制搭建了一条直接路径：Actor（演员）网络把状态映射成确定性动作，Criti"}],["meta",{"property":"og:url","content":"https://zpy560.github.io/Nav2ArticlesSite/rl/rl-series-16-ddpg"}],["meta",{"property":"og:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_16_actor_critic.png"}],["meta",{"property":"article:published_time","content":"2026-08-13"}],["meta",{"name":"twitter:title","content":"连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进"}],["meta",{"name":"twitter:description","content":"DQN（深度 Q 网络）可以比较有限个动作的价值，却无法在方向盘角度、加速度或机械臂力矩这样的连续空间里逐项枚举。Deep Deterministic Policy Gradient（深度确定性策略梯度，DDPG）为连续控制搭建了一条直接路径：Actor（演员）网络把状态映射成确定性动作，Criti"}],["meta",{"name":"twitter:image","content":"https://zpy560.github.io/Nav2ArticlesSite/article-assets/2026-08-13/rl_series_16_actor_critic.png"}]],"prev":{"text":"同一批数据多学几轮，策略为什么会崩？PPO 的裁剪目标讲透了","link":"/rl/rl-series-15-ppo"},"next":{"text":"评论家一高估，演员就钻空子：TD3 怎样给 DDPG 加上三道保险","link":"/rl/rl-series-17-td3"}},"headers":[],"relativePath":"rl/rl-series-16-ddpg.md","filePath":"rl/rl-series-16-ddpg.md","lastUpdated":null}'),s={name:"rl/rl-series-16-ddpg.md"};function p(c,a,_,u,b,m){return t(),r("div",null,[...a[0]||(a[0]=[i('<h1 id="连续动作不再靠枚举-ddpg-怎样让演员沿着评论家的梯度前进" tabindex="-1">连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进 <a class="header-anchor" href="#连续动作不再靠枚举-ddpg-怎样让演员沿着评论家的梯度前进" aria-label="Permalink to &quot;连续动作不再靠枚举：DDPG 怎样让演员沿着评论家的梯度前进&quot;">​</a></h1><p>DQN（深度 Q 网络）可以比较有限个动作的价值，却无法在方向盘角度、加速度或机械臂力矩这样的连续空间里逐项枚举。Deep Deterministic Policy Gradient（深度确定性策略梯度，DDPG）为连续控制搭建了一条直接路径：Actor（演员）网络把状态映射成确定性动作，Critic（评论家）网络为状态—动作对打分，演员沿着评论家关于动作的梯度调整输出，让预测 Q 值上升。</p><p>DDPG 同时继承了 DQN 的 Replay Buffer（回放缓冲区）和 Target Network（目标网络），因此可以重复使用旧数据，属于 Off-Policy（异策略）算法。但这套结构高度耦合：评论家一旦在某个动作附近错误地给出高分，演员会主动追逐并放大这个误差；确定性策略本身又没有随机探索，必须额外构造行为噪声。理解 DDPG 的关键不是记住四个网络，而是看清数据、梯度和时间尺度分别怎样流动。</p><h2 id="一、先给出整篇文章的结论" tabindex="-1">一、先给出整篇文章的结论 <a class="header-anchor" href="#一、先给出整篇文章的结论" aria-label="Permalink to &quot;一、先给出整篇文章的结论&quot;">​</a></h2><h3 id="_1-1-演员直接输出连续动作" tabindex="-1">1.1 演员直接输出连续动作 <a class="header-anchor" href="#_1-1-演员直接输出连续动作" aria-label="Permalink to &quot;1.1 演员直接输出连续动作&quot;">​</a></h3><p>确定性策略写作 (A=\\mu_\\theta(S))。相同状态和固定参数得到相同动作，不需要对连续动作执行 (\\arg\\max) 搜索。</p><h3 id="_1-2-评论家把动作质量变成可求导地形" tabindex="-1">1.2 评论家把动作质量变成可求导地形 <a class="header-anchor" href="#_1-2-评论家把动作质量变成可求导地形" aria-label="Permalink to &quot;1.2 评论家把动作质量变成可求导地形&quot;">​</a></h3><p>评论家估计 (Q_\\phi(s,a))。演员把自身输出送入评论家，并沿 (\\nabla_a Q_\\phi(s,a)) 指示的方向改变动作。</p><h3 id="_1-3-训练策略与行为策略不是一回事" tabindex="-1">1.3 训练策略与行为策略不是一回事 <a class="header-anchor" href="#_1-3-训练策略与行为策略不是一回事" aria-label="Permalink to &quot;1.3 训练策略与行为策略不是一回事&quot;">​</a></h3><p>目标演员是确定性的，采集数据时通常执行 (\\mu_\\theta(s)+\\epsilon)。噪声属于探索行为，不属于部署策略，也不应在评估时继续开启。</p><h3 id="_1-4-ddpg-样本复用强但稳定性脆弱" tabindex="-1">1.4 DDPG 样本复用强但稳定性脆弱 <a class="header-anchor" href="#_1-4-ddpg-样本复用强但稳定性脆弱" aria-label="Permalink to &quot;1.4 DDPG 样本复用强但稳定性脆弱&quot;">​</a></h3><p>回放缓冲区提高样本利用率，软目标网络减慢目标变化；单评论家的函数逼近误差仍可能被演员系统性利用，这正是 TD3（双延迟深度确定性策略梯度）要解决的问题。</p><p><img src="'+h+'" alt="DDPG 用确定性演员输出动作，再由评论家评价"></p><h2 id="二、连续动作为什么不能照搬-dqn" tabindex="-1">二、连续动作为什么不能照搬 DQN <a class="header-anchor" href="#二、连续动作为什么不能照搬-dqn" aria-label="Permalink to &quot;二、连续动作为什么不能照搬 DQN&quot;">​</a></h2><h3 id="_2-1-动作集合不可数" tabindex="-1">2.1 动作集合不可数 <a class="header-anchor" href="#_2-1-动作集合不可数" aria-label="Permalink to &quot;2.1 动作集合不可数&quot;">​</a></h3><p>若转角允许取区间内任意实数，网络不可能为每个候选动作设置一个输出节点。提高离散分辨率只能让动作数越来越大，并引入控制台阶。</p><h3 id="_2-2-每个状态求最优动作代价很高" tabindex="-1">2.2 每个状态求最优动作代价很高 <a class="header-anchor" href="#_2-2-每个状态求最优动作代价很高" aria-label="Permalink to &quot;2.2 每个状态求最优动作代价很高&quot;">​</a></h3><p>即使评论家能输入连续动作，计算 (\\arg\\max_a Q(s,a)) 仍需要数值优化。控制周期内反复求解非凸问题既慢又不稳定。</p><h3 id="_2-3-演员学习近似最大化映射" tabindex="-1">2.3 演员学习近似最大化映射 <a class="header-anchor" href="#_2-3-演员学习近似最大化映射" aria-label="Permalink to &quot;2.3 演员学习近似最大化映射&quot;">​</a></h3><p>DDPG 用神经网络 (\\mu_\\theta(s)) 直接产生评论家认为较好的动作，相当于把逐状态优化过程摊入演员训练。</p><h2 id="三、ddpg-的四个网络分别做什么" tabindex="-1">三、DDPG 的四个网络分别做什么 <a class="header-anchor" href="#三、ddpg-的四个网络分别做什么" aria-label="Permalink to &quot;三、DDPG 的四个网络分别做什么&quot;">​</a></h2><h3 id="_3-1-主演员产生当前策略动作" tabindex="-1">3.1 主演员产生当前策略动作 <a class="header-anchor" href="#_3-1-主演员产生当前策略动作" aria-label="Permalink to &quot;3.1 主演员产生当前策略动作&quot;">​</a></h3><p>(\\mu_\\theta(s)) 是需要学习和最终部署的确定性策略。训练时它参与演员损失，交互时还会叠加探索噪声。</p><h3 id="_3-2-主评论家学习动作价值" tabindex="-1">3.2 主评论家学习动作价值 <a class="header-anchor" href="#_3-2-主评论家学习动作价值" aria-label="Permalink to &quot;3.2 主评论家学习动作价值&quot;">​</a></h3><p>(Q_\\phi(s,a)) 接收状态和连续动作，输出标量价值。它根据缓冲区样本回归 Bellman（贝尔曼）目标。</p><h3 id="_3-3-目标演员生成下一状态动作" tabindex="-1">3.3 目标演员生成下一状态动作 <a class="header-anchor" href="#_3-3-目标演员生成下一状态动作" aria-label="Permalink to &quot;3.3 目标演员生成下一状态动作&quot;">​</a></h3><p>(\\mu_{\\theta_{targ}}(s&#39;)) 变化较慢，用于评论家目标，不负责当前演员的直接优化。</p><h3 id="_3-4-目标评论家生成自举价值" tabindex="-1">3.4 目标评论家生成自举价值 <a class="header-anchor" href="#_3-4-目标评论家生成自举价值" aria-label="Permalink to &quot;3.4 目标评论家生成自举价值&quot;">​</a></h3><p>(Q_{\\phi_{targ}}(s&#39;,a&#39;)) 与目标演员共同构造相对稳定的下一状态目标。两个目标网络都通过软更新追踪主网络。</p><h2 id="四、评论家的训练目标怎样构造" tabindex="-1">四、评论家的训练目标怎样构造 <a class="header-anchor" href="#四、评论家的训练目标怎样构造" aria-label="Permalink to &quot;四、评论家的训练目标怎样构造&quot;">​</a></h2><h3 id="_4-1-从回放池抽取转移" tabindex="-1">4.1 从回放池抽取转移 <a class="header-anchor" href="#_4-1-从回放池抽取转移" aria-label="Permalink to &quot;4.1 从回放池抽取转移&quot;">​</a></h3><p>一条样本至少包含 ((S_t,A_t,R_{t+1},S_{t+1},D_{t+1}))。动作必须是环境真正执行的行为动作，而不是去掉噪声后的演员原始输出。</p><h3 id="_4-2-下一状态动作来自目标演员" tabindex="-1">4.2 下一状态动作来自目标演员 <a class="header-anchor" href="#_4-2-下一状态动作来自目标演员" aria-label="Permalink to &quot;4.2 下一状态动作来自目标演员&quot;">​</a></h3><p>$$ A&#39; = \\mu_{\\theta_{targ}}(S&#39;) $$</p><p>基础 DDPG 的目标动作通常不额外加入 TD3 式平滑噪声。</p><h3 id="_4-3-评论家目标使用目标网络" tabindex="-1">4.3 评论家目标使用目标网络 <a class="header-anchor" href="#_4-3-评论家目标使用目标网络" aria-label="Permalink to &quot;4.3 评论家目标使用目标网络&quot;">​</a></h3><p>$$ Y=R+\\gamma(1-D)Q_{\\phi_{targ}}\\left(S&#39;,\\mu_{\\theta_{targ}}(S&#39;)\\right) $$</p><p>自然终止时去掉自举项，外部时间截断通常仍应保留下一状态价值。</p><h3 id="_4-4-主评论家最小化回归误差" tabindex="-1">4.4 主评论家最小化回归误差 <a class="header-anchor" href="#_4-4-主评论家最小化回归误差" aria-label="Permalink to &quot;4.4 主评论家最小化回归误差&quot;">​</a></h3><p>$$ L_Q(\\phi)=\\mathbb E\\left[\\left(Q_\\phi(S,A)-Y\\right)^2\\right] $$</p><p>目标分支需要停止梯度，当前损失只更新主评论家参数。</p><p><img src="'+l+'" alt="DDPG 评论家使用目标演员和目标评论家构造自举目标"></p><h2 id="五、确定性策略梯度怎样更新演员" tabindex="-1">五、确定性策略梯度怎样更新演员 <a class="header-anchor" href="#五、确定性策略梯度怎样更新演员" aria-label="Permalink to &quot;五、确定性策略梯度怎样更新演员&quot;">​</a></h2><h3 id="_5-1-演员目标是提高评论家评分" tabindex="-1">5.1 演员目标是提高评论家评分 <a class="header-anchor" href="#_5-1-演员目标是提高评论家评分" aria-label="Permalink to &quot;5.1 演员目标是提高评论家评分&quot;">​</a></h3><p>常见实现最小化：</p><p>$$ L_\\mu(\\theta)=-\\mathbb E_{S\\sim\\mathcal D}\\left[Q_\\phi(S,\\mu_\\theta(S))\\right] $$</p><p>负号把最大化 Q 值转换成梯度下降接口。</p><h3 id="_5-2-梯度先穿过评论家的动作输入" tabindex="-1">5.2 梯度先穿过评论家的动作输入 <a class="header-anchor" href="#_5-2-梯度先穿过评论家的动作输入" aria-label="Permalink to &quot;5.2 梯度先穿过评论家的动作输入&quot;">​</a></h3><p>链式法则写作：</p><p>$$ \\nabla_\\theta J\\approx\\mathbb E\\left[\\nabla_a Q_\\phi(S,a)|<em>{a=\\mu</em>\\theta(S)}\\nabla_\\theta\\mu_\\theta(S)\\right] $$</p><p>评论家告诉演员“动作往哪里改会提高分数”，演员再把这个方向传回自身参数。</p><h3 id="_5-3-演员更新时不应优化评论家参数" tabindex="-1">5.3 演员更新时不应优化评论家参数 <a class="header-anchor" href="#_5-3-演员更新时不应优化评论家参数" aria-label="Permalink to &quot;5.3 演员更新时不应优化评论家参数&quot;">​</a></h3><p>需要保留评论家对动作的梯度，却不希望演员损失改变评论家权重。实现可暂时冻结评论家参数，仍允许梯度穿过其运算到达动作。</p><h3 id="_5-4-演员只会迎合当前评论家" tabindex="-1">5.4 演员只会迎合当前评论家 <a class="header-anchor" href="#_5-4-演员只会迎合当前评论家" aria-label="Permalink to &quot;5.4 演员只会迎合当前评论家&quot;">​</a></h3><p>演员看不到真实环境回报，只看评论家局部地形。评论家错误的陡峭高峰会成为演员主动追逐的目标。</p><p><img src="'+o+'" alt="演员梯度经评论家的动作方向传回确定性策略"></p><h2 id="六、经验回放为什么让-ddpg-成为异策略算法" tabindex="-1">六、经验回放为什么让 DDPG 成为异策略算法 <a class="header-anchor" href="#六、经验回放为什么让-ddpg-成为异策略算法" aria-label="Permalink to &quot;六、经验回放为什么让 DDPG 成为异策略算法&quot;">​</a></h2><h3 id="_6-1-数据来自历史行为策略" tabindex="-1">6.1 数据来自历史行为策略 <a class="header-anchor" href="#_6-1-数据来自历史行为策略" aria-label="Permalink to &quot;6.1 数据来自历史行为策略&quot;">​</a></h3><p>缓冲区混合了不同训练阶段、不同探索噪声下的转移。当前演员可以使用这些旧状态动作训练评论家。</p><h3 id="_6-2-bellman-目标不要求动作来自当前演员" tabindex="-1">6.2 Bellman 目标不要求动作来自当前演员 <a class="header-anchor" href="#_6-2-bellman-目标不要求动作来自当前演员" aria-label="Permalink to &quot;6.2 Bellman 目标不要求动作来自当前演员&quot;">​</a></h3><p>评论家对缓冲区真实执行动作 (A) 回归目标，而下一状态自举动作由当前目标演员产生。这种结构支持异策略数据复用。</p><h3 id="_6-3-数据复用不等于任意日志都有效" tabindex="-1">6.3 数据复用不等于任意日志都有效 <a class="header-anchor" href="#_6-3-数据复用不等于任意日志都有效" aria-label="Permalink to &quot;6.3 数据复用不等于任意日志都有效&quot;">​</a></h3><p>若旧数据覆盖不到当前策略附近、奖励定义已变化或动作单位不一致，评论家外推会非常危险。异策略只是允许分布不同，不保证分布差异无代价。</p><h3 id="_6-4-回放预热避免过早互相放大" tabindex="-1">6.4 回放预热避免过早互相放大 <a class="header-anchor" href="#_6-4-回放预热避免过早互相放大" aria-label="Permalink to &quot;6.4 回放预热避免过早互相放大&quot;">​</a></h3><p>训练初期演员和评论家均随机，少量相邻数据容易让评论家形成偶然高峰。通常先收集一段随机或带噪数据，再启动梯度更新。</p><h2 id="七、确定性策略怎样探索" tabindex="-1">七、确定性策略怎样探索 <a class="header-anchor" href="#七、确定性策略怎样探索" aria-label="Permalink to &quot;七、确定性策略怎样探索&quot;">​</a></h2><h3 id="_7-1-行为动作叠加外部噪声" tabindex="-1">7.1 行为动作叠加外部噪声 <a class="header-anchor" href="#_7-1-行为动作叠加外部噪声" aria-label="Permalink to &quot;7.1 行为动作叠加外部噪声&quot;">​</a></h3><p>$$ A_t=\\operatorname{clip}\\left(\\mu_\\theta(S_t)+\\epsilon_t,a_{low},a_{high}\\right) $$</p><p>噪声可用高斯过程，也可使用 Ornstein-Uhlenbeck Process（奥恩斯坦—乌伦贝克过程）形成时间相关探索。</p><h3 id="_7-2-探索噪声只用于数据采集" tabindex="-1">7.2 探索噪声只用于数据采集 <a class="header-anchor" href="#_7-2-探索噪声只用于数据采集" aria-label="Permalink to &quot;7.2 探索噪声只用于数据采集&quot;">​</a></h3><p>评论家缓冲区保存实际带噪动作；演员训练仍输出无噪动作，评估和部署通常关闭噪声。</p><h3 id="_7-3-噪声尺度必须按动作维度设计" tabindex="-1">7.3 噪声尺度必须按动作维度设计 <a class="header-anchor" href="#_7-3-噪声尺度必须按动作维度设计" aria-label="Permalink to &quot;7.3 噪声尺度必须按动作维度设计&quot;">​</a></h3><p>转角和加速度的物理范围不同，使用相同绝对噪声会造成探索强度失衡。应先归一化动作，再按维度检查实际扰动。</p><h3 id="_7-4-裁剪会改变噪声分布" tabindex="-1">7.4 裁剪会改变噪声分布 <a class="header-anchor" href="#_7-4-裁剪会改变噪声分布" aria-label="Permalink to &quot;7.4 裁剪会改变噪声分布&quot;">​</a></h3><p>大量动作撞到上下界时，行为分布在边界堆积，回放数据失衡。需要监控饱和率，而不是只记录噪声标准差。</p><p><img src="'+n+'" alt="训练策略、探索行为和评估策略必须明确分开"></p><h2 id="八、软目标网络怎样稳定训练" tabindex="-1">八、软目标网络怎样稳定训练 <a class="header-anchor" href="#八、软目标网络怎样稳定训练" aria-label="Permalink to &quot;八、软目标网络怎样稳定训练&quot;">​</a></h2><h3 id="_8-1-目标参数缓慢追踪主参数" tabindex="-1">8.1 目标参数缓慢追踪主参数 <a class="header-anchor" href="#_8-1-目标参数缓慢追踪主参数" aria-label="Permalink to &quot;8.1 目标参数缓慢追踪主参数&quot;">​</a></h3><p>$$ \\theta_{targ}\\leftarrow\\rho\\theta_{targ}+(1-\\rho)\\theta $$</p><p>评论家目标参数同样更新。也可用 (\\tau=1-\\rho) 表示新参数占比，阅读配置时必须确认定义。</p><h3 id="_8-2-软更新让目标连续变化" tabindex="-1">8.2 软更新让目标连续变化 <a class="header-anchor" href="#_8-2-软更新让目标连续变化" aria-label="Permalink to &quot;8.2 软更新让目标连续变化&quot;">​</a></h3><p>相比周期硬复制，每步少量混合减少目标突跳，适合演员与评论家持续在线更新。</p><h3 id="_8-3-目标滞后也会带来偏差" tabindex="-1">8.3 目标滞后也会带来偏差 <a class="header-anchor" href="#_8-3-目标滞后也会带来偏差" aria-label="Permalink to &quot;8.3 目标滞后也会带来偏差&quot;">​</a></h3><p>追踪过慢时，目标网络代表过时策略与价值；追踪过快则失去稳定作用。它是时间尺度折中，不是越慢越好。</p><h2 id="九、动作压缩和物理缩放怎样处理" tabindex="-1">九、动作压缩和物理缩放怎样处理 <a class="header-anchor" href="#九、动作压缩和物理缩放怎样处理" aria-label="Permalink to &quot;九、动作压缩和物理缩放怎样处理&quot;">​</a></h2><h3 id="_9-1-tanh-把原始输出限制到标准区间" tabindex="-1">9.1 Tanh 把原始输出限制到标准区间 <a class="header-anchor" href="#_9-1-tanh-把原始输出限制到标准区间" aria-label="Permalink to &quot;9.1 Tanh 把原始输出限制到标准区间&quot;">​</a></h3><p>网络末层常用 Tanh（双曲正切）输出 ([-1,1])，再线性映射到环境动作上下界。</p><h3 id="_9-2-非对称动作范围需要偏移" tabindex="-1">9.2 非对称动作范围需要偏移 <a class="header-anchor" href="#_9-2-非对称动作范围需要偏移" aria-label="Permalink to &quot;9.2 非对称动作范围需要偏移&quot;">​</a></h3><p>物理范围为 ([a_{low},a_{high}]) 时，应同时使用尺度与中心偏移，不能只乘最大绝对值。</p><h3 id="_9-3-评论家必须接收一致动作表示" tabindex="-1">9.3 评论家必须接收一致动作表示 <a class="header-anchor" href="#_9-3-评论家必须接收一致动作表示" aria-label="Permalink to &quot;9.3 评论家必须接收一致动作表示&quot;">​</a></h3><p>可以让评论家接收归一化动作，也可以接收物理动作，但回放、演员输出、目标动作和环境接口必须统一。</p><h3 id="_9-4-饱和区梯度可能变小" tabindex="-1">9.4 饱和区梯度可能变小 <a class="header-anchor" href="#_9-4-饱和区梯度可能变小" aria-label="Permalink to &quot;9.4 饱和区梯度可能变小&quot;">​</a></h3><p>Tanh 接近边界时导数趋近零，演员难以从饱和动作返回。若训练长期顶在边界，应检查奖励、动作范围和初始化。</p><h2 id="十、ddpg-为什么容易不稳定" tabindex="-1">十、DDPG 为什么容易不稳定 <a class="header-anchor" href="#十、ddpg-为什么容易不稳定" aria-label="Permalink to &quot;十、DDPG 为什么容易不稳定&quot;">​</a></h2><h3 id="_10-1-单评论家误差会直接驱动演员" tabindex="-1">10.1 单评论家误差会直接驱动演员 <a class="header-anchor" href="#_10-1-单评论家误差会直接驱动演员" aria-label="Permalink to &quot;10.1 单评论家误差会直接驱动演员&quot;">​</a></h3><p>评论家在未充分覆盖动作上给出虚假高值，演员会把动作推向该区域，随后目标值继续上升，形成正反馈。</p><h3 id="_10-2-确定性策略缺少分布缓冲" tabindex="-1">10.2 确定性策略缺少分布缓冲 <a class="header-anchor" href="#_10-2-确定性策略缺少分布缓冲" aria-label="Permalink to &quot;10.2 确定性策略缺少分布缓冲&quot;">​</a></h3><p>随机策略会在邻域采样多个动作，DDPG 的演员只优化单个输出点，更容易利用 Q 地形的尖锐误差。</p><h3 id="_10-3-同时快速更新会互相追逐" tabindex="-1">10.3 同时快速更新会互相追逐 <a class="header-anchor" href="#_10-3-同时快速更新会互相追逐" aria-label="Permalink to &quot;10.3 同时快速更新会互相追逐&quot;">​</a></h3><p>评论家追随不断变化的演员，演员又追随尚未稳定的评论家。两个学习率和更新次数不匹配时，闭环容易振荡。</p><h3 id="_10-4-训练成功对随机种子敏感" tabindex="-1">10.4 训练成功对随机种子敏感 <a class="header-anchor" href="#_10-4-训练成功对随机种子敏感" aria-label="Permalink to &quot;10.4 训练成功对随机种子敏感&quot;">​</a></h3><p>初始探索轨迹决定缓冲区覆盖，早期评论家误差又决定演员方向。单个成功种子不能证明算法稳健。</p><h2 id="十一、应监控哪些内部指标" tabindex="-1">十一、应监控哪些内部指标 <a class="header-anchor" href="#十一、应监控哪些内部指标" aria-label="Permalink to &quot;十一、应监控哪些内部指标&quot;">​</a></h2><h3 id="_11-1-预测-q-值与实现回报" tabindex="-1">11.1 预测 Q 值与实现回报 <a class="header-anchor" href="#_11-1-预测-q-值与实现回报" aria-label="Permalink to &quot;11.1 预测 Q 值与实现回报&quot;">​</a></h3><p>固定评估状态动作，比较评论家预测与从当前策略采样得到的折扣回报。Q 值上升但真实回报停滞是高估警报。</p><h3 id="_11-2-动作均值、方差与饱和率" tabindex="-1">11.2 动作均值、方差与饱和率 <a class="header-anchor" href="#_11-2-动作均值、方差与饱和率" aria-label="Permalink to &quot;11.2 动作均值、方差与饱和率&quot;">​</a></h3><p>分别记录无噪演员动作、带噪行为动作和环境裁剪后的实际动作，避免把探索变化误判为策略学习。</p><h3 id="_11-3-评论家误差和梯度范数" tabindex="-1">11.3 评论家误差和梯度范数 <a class="header-anchor" href="#_11-3-评论家误差和梯度范数" aria-label="Permalink to &quot;11.3 评论家误差和梯度范数&quot;">​</a></h3><p>TD 误差均值、尾部、评论家梯度、演员梯度和目标网络差距能帮助识别数值爆炸与时间尺度失衡。</p><h3 id="_11-4-缓冲区覆盖与年龄" tabindex="-1">11.4 缓冲区覆盖与年龄 <a class="header-anchor" href="#_11-4-缓冲区覆盖与年龄" aria-label="Permalink to &quot;11.4 缓冲区覆盖与年龄&quot;">​</a></h3><p>记录状态区域、动作区间、终止原因和样本年龄。大缓冲区提高多样性，也可能保留过多陈旧数据。</p><h2 id="十二、训练与评估协议怎样分开" tabindex="-1">十二、训练与评估协议怎样分开 <a class="header-anchor" href="#十二、训练与评估协议怎样分开" aria-label="Permalink to &quot;十二、训练与评估协议怎样分开&quot;">​</a></h2><h3 id="_12-1-训练回报包含探索噪声" tabindex="-1">12.1 训练回报包含探索噪声 <a class="header-anchor" href="#_12-1-训练回报包含探索噪声" aria-label="Permalink to &quot;12.1 训练回报包含探索噪声&quot;">​</a></h3><p>训练回报反映行为策略，不等于确定性演员本身性能。评估应关闭探索噪声并冻结所有参数和统计量。</p><h3 id="_12-2-评估不能写入回放池" tabindex="-1">12.2 评估不能写入回放池 <a class="header-anchor" href="#_12-2-评估不能写入回放池" aria-label="Permalink to &quot;12.2 评估不能写入回放池&quot;">​</a></h3><p>评估轨迹若进入训练数据，独立评估就被污染。数据路径和随机种子需要隔离。</p><h3 id="_12-3-多种子报告失败运行" tabindex="-1">12.3 多种子报告失败运行 <a class="header-anchor" href="#_12-3-多种子报告失败运行" aria-label="Permalink to &quot;12.3 多种子报告失败运行&quot;">​</a></h3><p>至少报告中位数、离散程度、最差运行和达到阈值的环境步数，不能只展示最高回报曲线。</p><h2 id="十三、自动驾驶中-ddpg-能做什么" tabindex="-1">十三、自动驾驶中 DDPG 能做什么 <a class="header-anchor" href="#十三、自动驾驶中-ddpg-能做什么" aria-label="Permalink to &quot;十三、自动驾驶中 DDPG 能做什么&quot;">​</a></h2><h3 id="_13-1-可输出连续规控参数" tabindex="-1">13.1 可输出连续规控参数 <a class="header-anchor" href="#_13-1-可输出连续规控参数" aria-label="Permalink to &quot;13.1 可输出连续规控参数&quot;">​</a></h3><p>演员可以产生目标曲率、加速度、跟驰参数或轨迹代价权重，减少离散动作分辨率限制。</p><h3 id="_13-2-评论家不等于可验证代价函数" tabindex="-1">13.2 评论家不等于可验证代价函数 <a class="header-anchor" href="#_13-2-评论家不等于可验证代价函数" aria-label="Permalink to &quot;13.2 评论家不等于可验证代价函数&quot;">​</a></h3><p>Q 值是训练数据和奖励下的近似期望，无法替代碰撞检查、动力学验证或规则约束。</p><h3 id="_13-3-探索噪声应限制在受控环境" tabindex="-1">13.3 探索噪声应限制在受控环境 <a class="header-anchor" href="#_13-3-探索噪声应限制在受控环境" aria-label="Permalink to &quot;13.3 探索噪声应限制在受控环境&quot;">​</a></h3><p>带噪行为适合仿真和封闭场地，不应在公开道路把随机控制当成常规在线学习。</p><h3 id="_13-4-安全层修改动作会改变数据语义" tabindex="-1">13.4 安全层修改动作会改变数据语义 <a class="header-anchor" href="#_13-4-安全层修改动作会改变数据语义" aria-label="Permalink to &quot;13.4 安全层修改动作会改变数据语义&quot;">​</a></h3><p>若安全屏蔽覆盖演员动作，缓冲区必须保存真实执行动作，并额外记录提议动作与介入原因，才能分析策略和安全层各自贡献。</p><p><img src="'+d+'" alt="自动驾驶 DDPG 仍需动作变换、可行性检查和安全层"></p><h2 id="十四、一个最小实验怎样设计" tabindex="-1">十四、一个最小实验怎样设计 <a class="header-anchor" href="#十四、一个最小实验怎样设计" aria-label="Permalink to &quot;十四、一个最小实验怎样设计&quot;">​</a></h2><h3 id="_14-1-从低维连续控制环境开始" tabindex="-1">14.1 从低维连续控制环境开始 <a class="header-anchor" href="#_14-1-从低维连续控制环境开始" aria-label="Permalink to &quot;14.1 从低维连续控制环境开始&quot;">​</a></h3><p>使用 Pendulum（摆杆）等任务，先验证动作范围、终止掩码、目标网络和评论家梯度，再进入复杂车辆模型。</p><h3 id="_14-2-与随机策略和经典控制基线比较" tabindex="-1">14.2 与随机策略和经典控制基线比较 <a class="header-anchor" href="#_14-2-与随机策略和经典控制基线比较" aria-label="Permalink to &quot;14.2 与随机策略和经典控制基线比较&quot;">​</a></h3><p>DDPG 跑通不代表有价值。应在相同场景、预算和指标下比较随机策略、比例控制或其他可解释基线。</p><h3 id="_14-3-做目标网络和噪声消融" tabindex="-1">14.3 做目标网络和噪声消融 <a class="header-anchor" href="#_14-3-做目标网络和噪声消融" aria-label="Permalink to &quot;14.3 做目标网络和噪声消融&quot;">​</a></h3><p>分别改变软更新速度、探索噪声尺度和回放预热长度，观察覆盖、Q 值偏差与多种子稳定性。</p><h2 id="十五、最常见的实现错误" tabindex="-1">十五、最常见的实现错误 <a class="header-anchor" href="#十五、最常见的实现错误" aria-label="Permalink to &quot;十五、最常见的实现错误&quot;">​</a></h2><h3 id="_15-1-评论家目标没有停止梯度" tabindex="-1">15.1 评论家目标没有停止梯度 <a class="header-anchor" href="#_15-1-评论家目标没有停止梯度" aria-label="Permalink to &quot;15.1 评论家目标没有停止梯度&quot;">​</a></h3><p>目标演员和目标评论家只生成标签，不应接收主评论家损失梯度。</p><h3 id="_15-2-演员损失更新了评论家" tabindex="-1">15.2 演员损失更新了评论家 <a class="header-anchor" href="#_15-2-演员损失更新了评论家" aria-label="Permalink to &quot;15.2 演员损失更新了评论家&quot;">​</a></h3><p>若评论家参数仍在演员优化器中或未清理梯度，可能被错误修改。必须明确参数所有权。</p><h3 id="_15-3-缓冲区保存了错误动作" tabindex="-1">15.3 缓冲区保存了错误动作 <a class="header-anchor" href="#_15-3-缓冲区保存了错误动作" aria-label="Permalink to &quot;15.3 缓冲区保存了错误动作&quot;">​</a></h3><p>环境接收带噪且裁剪后的动作，评论家输入却保存无噪动作，会让状态转移与动作标签不匹配。</p><h3 id="_15-4-软更新系数方向写反" tabindex="-1">15.4 软更新系数方向写反 <a class="header-anchor" href="#_15-4-软更新系数方向写反" aria-label="Permalink to &quot;15.4 软更新系数方向写反&quot;">​</a></h3><p>不同代码用 (\\rho) 或 (\\tau) 表示不同部分。必须用数值测试确认目标参数每步只移动小距离。</p><h3 id="_15-5-终止与截断仍混为一个标记" tabindex="-1">15.5 终止与截断仍混为一个标记 <a class="header-anchor" href="#_15-5-终止与截断仍混为一个标记" aria-label="Permalink to &quot;15.5 终止与截断仍混为一个标记&quot;">​</a></h3><p>自然终止停止自举，外部时间上限通常继续自举。错误处理会让价值在回合边界系统性偏低。</p><h2 id="十六、学到什么程度才算掌握" tabindex="-1">十六、学到什么程度才算掌握 <a class="header-anchor" href="#十六、学到什么程度才算掌握" aria-label="Permalink to &quot;十六、学到什么程度才算掌握&quot;">​</a></h2><h3 id="_16-1-能画出四网络和两条梯度路径" tabindex="-1">16.1 能画出四网络和两条梯度路径 <a class="header-anchor" href="#_16-1-能画出四网络和两条梯度路径" aria-label="Permalink to &quot;16.1 能画出四网络和两条梯度路径&quot;">​</a></h3><p>应能指出评论家目标使用哪些目标网络，演员梯度怎样穿过主评论家的动作输入，以及每项损失更新哪些参数。</p><h3 id="_16-2-能区分三种动作" tabindex="-1">16.2 能区分三种动作 <a class="header-anchor" href="#_16-2-能区分三种动作" aria-label="Permalink to &quot;16.2 能区分三种动作&quot;">​</a></h3><p>需要分别说明演员原始动作、带噪行为动作和环境实际执行动作，知道哪一种进入回放和评估。</p><h3 id="_16-3-能解释异策略样本效率与风险" tabindex="-1">16.3 能解释异策略样本效率与风险 <a class="header-anchor" href="#_16-3-能解释异策略样本效率与风险" aria-label="Permalink to &quot;16.3 能解释异策略样本效率与风险&quot;">​</a></h3><p>回放允许复用旧数据，也扩大当前策略与数据分布差异。评论家在缺少覆盖区域的外推是主要风险。</p><h3 id="_16-4-能准备进入-td3" tabindex="-1">16.4 能准备进入 TD3 <a class="header-anchor" href="#_16-4-能准备进入-td3" aria-label="Permalink to &quot;16.4 能准备进入 TD3&quot;">​</a></h3><p>下一篇将用双评论家取较小值、延迟演员更新和目标策略平滑，针对 DDPG 中演员利用评论家误差的问题逐项改造。</p><h2 id="参考资料" tabindex="-1">参考资料 <a class="header-anchor" href="#参考资料" aria-label="Permalink to &quot;参考资料&quot;">​</a></h2><p><a href="https://github.com/datawhalechina/easy-rl/blob/master/docs/chapter12/chapter12.md" target="_blank" rel="noreferrer">《蘑菇书 EasyRL》第十二章深度确定性策略梯度</a></p><p><a href="https://arxiv.org/abs/1509.02971" target="_blank" rel="noreferrer">Lillicrap 等《Continuous Control with Deep Reinforcement Learning》</a></p><p><a href="https://proceedings.mlr.press/v32/silver14.html" target="_blank" rel="noreferrer">Silver 等《Deterministic Policy Gradient Algorithms》</a></p><p><a href="https://spinningup.openai.com/en/latest/algorithms/ddpg.html" target="_blank" rel="noreferrer">OpenAI Spinning Up DDPG 文档</a></p>',160)])])}const f=e(s,[["render",p]]);export{P as __pageData,f as default};
